ALTER TABLE projects ADD COLUMN IF NOT EXISTS address VARCHAR(500);
ALTER TABLE projects ADD COLUMN IF NOT EXISTS created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE projects ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE units ADD COLUMN IF NOT EXISTS facing VARCHAR(40);
ALTER TABLE units ADD COLUMN IF NOT EXISTS parking VARCHAR(120);
ALTER TABLE units ADD COLUMN IF NOT EXISTS amenities VARCHAR(1000);
ALTER TABLE units ADD COLUMN IF NOT EXISTS reserved_until TIMESTAMP WITH TIME ZONE;
ALTER TABLE units ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE units ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP;
CREATE TABLE project_wings (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, code VARCHAR(40) NOT NULL, name VARCHAR(120) NOT NULL, UNIQUE(project_id,code));
CREATE TABLE project_floors (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, wing_id UUID NOT NULL REFERENCES project_wings(id) ON DELETE CASCADE, floor_number INT NOT NULL, label VARCHAR(60), UNIQUE(wing_id,floor_number));
CREATE TABLE unit_price_history (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, unit_id UUID NOT NULL REFERENCES units(id) ON DELETE CASCADE, old_price DECIMAL(15,2), new_price DECIMAL(15,2) NOT NULL, reason VARCHAR(300), changed_by UUID REFERENCES users(id), changed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE unit_status_history (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, unit_id UUID NOT NULL REFERENCES units(id) ON DELETE CASCADE, old_status VARCHAR(30), new_status VARCHAR(30) NOT NULL, reason VARCHAR(300), changed_by UUID REFERENCES users(id), changed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE unit_reservations (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, unit_id UUID NOT NULL REFERENCES units(id), reserved_by UUID NOT NULL REFERENCES users(id), expires_at TIMESTAMP WITH TIME ZONE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_units_status ON units(status); CREATE INDEX idx_units_project_status ON units(project_id,status);
